import { z } from 'zod';
export const metatagsSchema = z
    .record(z.string(), z.string().nonempty())
    .optional()
    .describe('Meta tags added to every page. Must be a valid key-value pair.');
const SEO_PATH_SEGMENT = /^[^\s/\\?#]+$/;
function isCanonicalSeoPath(value) {
    return value
        .split('/')
        .every((segment) => SEO_PATH_SEGMENT.test(segment) && segment !== '.' && segment !== '..');
}
export const seoPathSchema = z.object({
    path: z
        .string()
        .nonempty()
        .refine(isCanonicalSeoPath, 'Must be a slash-delimited folder path relative to the docs root, e.g. `guides/v2`. Each segment must be non-empty and must not be `.` or `..`, and the path must not start or end with a slash or contain whitespace, backslashes, `?`, or `#`.')
        .describe('Folder path relative to the docs root, e.g. `guides/v2`. Applies to every page under that folder.'),
    metatags: z
        .record(z.string(), z.string().nonempty())
        .describe('Meta tags added to every page under `path`. Must be a valid key-value pair.'),
});
export const seoPathsSchema = z
    .array(seoPathSchema)
    .refine((value) => {
    const paths = value.map((entry) => entry.path);
    return new Set(paths).size === paths.length;
}, 'Each path can only be used once')
    .describe('Meta tags scoped to a folder. Longer paths override shorter ones, which override `metatags`. Page frontmatter overrides both.');
export const seoOrganizationSchema = z
    .object({
    id: z
        .string()
        .url()
        .optional()
        .describe('Stable `@id` URL identifying your organization across pages, e.g. `https://example.com/#organization`. Defaults to `<site origin>/#organization`.'),
    name: z
        .string()
        .nonempty()
        .optional()
        .describe('Organization name. Defaults to the site name.'),
    legalName: z.string().nonempty().optional().describe('Registered legal name.'),
    url: z.string().url().optional().describe('Canonical organization homepage URL.'),
    logo: z
        .string()
        .url()
        .optional()
        .describe('Canonical logo URL used in structured data. Defaults to the docs logo.'),
    sameAs: z
        .array(z.string().url())
        .optional()
        .describe('URLs of official profiles, e.g. X, LinkedIn, GitHub.'),
})
    .describe('Organization entity emitted in structured data (JSON-LD) on every page.');
export const seoSchema = z
    .object({
    metatags: metatagsSchema.optional(),
    paths: seoPathsSchema.optional(),
    organization: seoOrganizationSchema.optional(),
    indexing: z
        .enum(['navigable', 'all'])
        .optional()
        .describe('Specify which pages to be indexed by search engines. Setting `navigable` indexes pages that are set in navigation, `all` indexes all pages. Defaults to `navigable`.'),
    trailingSlash: z
        .boolean()
        .optional()
        .describe('Emit trailing-slash URLs consistently across canonical tags, `og:url`, the sitemap, and generated internal links. Does not change page routes. Defaults to `false`.'),
})
    .describe('SEO indexing configurations');
